package managedviewer

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/ifuryst/open-browser-use/internal/managedprotocol"
)

// The fixture is generated by the production JS bridge. Unlike a hand-written
// cleanup mock, it retains the previous lease's receipt in the second Begin.
func TestHumanActualBridgeDisconnectConfirmsCurrentLease(t *testing.T) {
	data, err := os.ReadFile("testdata/human-disconnect-fixture.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Version     int
		FirstEnd    json.RawMessage `json:"firstEnd"`
		SecondBegin json.RawMessage `json:"secondBegin"`
		Disconnect  json.RawMessage
		Evidence    struct {
			Waited     bool `json:"disconnectWaitedForOriginalRelease"`
			CloseCalls []int
		}
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if fixture.Version != 1 || !fixture.Evidence.Waited || len(fixture.Evidence.CloseCalls) != 2 || fixture.Evidence.CloseCalls[0] != 1 || fixture.Evidence.CloseCalls[1] != 1 {
		t.Fatal("fixture does not establish two original releases")
	}
	begin, err := object(fixture.SecondBegin)
	if err != nil {
		t.Fatal(err)
	}
	state, err := object(begin["status"])
	if err != nil {
		t.Fatal(err)
	}
	human, err := managedprotocol.ParseHumanState(state["human"])
	if err != nil || human == nil || human.State != "active" {
		t.Fatalf("second lease is not active: %s, %v", state["human"], err)
	}
	oldReceipt, err := managedprotocol.ParseHumanCleanup(state["humanCleanup"])
	if err != nil || oldReceipt == nil || oldReceipt.LeaseID == human.LeaseID {
		t.Fatal("fixture must retain the distinct previous lease receipt")
	}
	connection := &connection{humanClaimed: true, humanLease: human.LeaseID}
	if err := connection.confirmCleanup(fixture.Disconnect); err != nil {
		t.Fatalf("actual bridge disconnect rejected: %v", err)
	}
	if _, err := publicState(fixture.Disconnect); err == nil {
		t.Fatal("cleanup receipt must not grant live viewer authority")
	}

	// Reconstruct the exact former disconnect shape from the actual last
	// status. Merely clearing the selected tab cannot release the current lease.
	t.Run("former_last_status_snapshot", func(t *testing.T) {
		state["connected"] = jsonBytes(false)
		state["selectedTabId"] = jsonBytes(nil)
		state["stream"] = jsonBytes(map[string]any{"state": "idle", "streamId": nil})
		old := jsonBytes(map[string]any{"disconnected": true, "status": state})
		if err := connection.confirmCleanup(old); err == nil {
			t.Fatal("old active human snapshot was accepted as cleanup")
		}
	})
	for name, mutate := range map[string]func(map[string]json.RawMessage){
		"old_lease_receipt": func(status map[string]json.RawMessage) { status["humanCleanup"] = jsonBytes(oldReceipt) },
		"missing_receipt":   func(status map[string]json.RawMessage) { delete(status, "humanCleanup") },
		"pending_cleanup":   func(status map[string]json.RawMessage) { status["cleanupPending"] = jsonBytes(1) },
		"unknown_cleanup": func(status map[string]json.RawMessage) {
			status["cleanupError"] = jsonBytes("synthetic release unconfirmed")
		},
	} {
		t.Run(name, func(t *testing.T) {
			copy, err := object(fixture.Disconnect)
			if err != nil {
				t.Fatal(err)
			}
			status, err := object(copy["status"])
			if err != nil {
				t.Fatal(err)
			}
			mutate(status)
			copy["status"] = jsonBytes(status)
			if err := connection.confirmCleanup(jsonBytes(copy)); err == nil {
				t.Fatal("unconfirmed or unrelated cleanup was accepted")
			}
		})
	}
}
